{
  "outcome": "escalate",
  "rationale": "We are escalating this claim for further investigation because automated findings indicate it is unclear whether an exclusion applies due to open facts regarding whether the claimant was carrying property for potential compensation. Section [PLUS-6.2] governs this decision, which mandates escalation when material facts are open to more than one reasonable reading.",
  "citations": [
    {
      "clause_id": "PLUS-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
